"""Consistency checks and summary stats for the disclosure audit.

Usage:  python check.py [path/to/incidents.csv]

Pure standard library so Priya/Morgan can run it anywhere.
"""
import csv
import sys
from collections import Counter, defaultdict
from datetime import date
from pathlib import Path

HERE = Path(__file__).resolve().parent
DEFAULT = HERE.parent / "data" / "incidents.csv"

F_FIELDS = [
    "f_description", "f_timeline", "f_root_cause", "f_affected_scope",
    "f_mitigation", "f_prevention", "f_contact",
]
F_VALUES = {"present", "partial", "absent", "n.a."}
SURFACED = {"developer", "press", "researcher", "user", "regulator", "other"}
THRESHOLD = {"yes", "likely", "unlikely", "no"}


def parse_date(s):
    s = (s or "").strip()
    if s in {"", "unknown", "none"}:
        return None
    y, m, d = s.split("-")
    return date(int(y), int(m), int(d))


def completeness(row):
    vals = [row[f] for f in F_FIELDS if row[f] != "n.a."]
    if not vals:
        return None
    score = sum(1.0 if v == "present" else 0.5 if v == "partial" else 0.0 for v in vals)
    return round(score / len(vals), 2)


def main(path):
    rows = list(csv.DictReader(open(path, newline="", encoding="utf-8")))
    problems = []
    ids = Counter(r["incident_id"] for r in rows)

    for r in rows:
        rid = r["incident_id"]
        if ids[rid] > 1:
            problems.append(f"{rid}: duplicate incident_id")
        for f in F_FIELDS:
            if r[f] not in F_VALUES:
                problems.append(f"{rid}: {f}={r[f]!r} not in {sorted(F_VALUES)}")
        if r["surfaced_by"] not in SURFACED:
            problems.append(f"{rid}: surfaced_by={r['surfaced_by']!r}")
        if r["would_meet_rule_threshold"] not in THRESHOLD:
            problems.append(f"{rid}: would_meet_rule_threshold={r['would_meet_rule_threshold']!r}")
        if r["would_meet_rule_threshold"] in {"yes", "likely"} and not r["threshold_rationale"].strip():
            problems.append(f"{rid}: threshold yes/likely needs a rationale")
        inc, dev = parse_date(r["incident_date"]), parse_date(r["first_developer_disclosure_date"])
        if inc and dev:
            calc = (dev - inc).days
            if r["days_to_disclosure"].strip() and int(r["days_to_disclosure"]) != calc:
                problems.append(f"{rid}: days_to_disclosure={r['days_to_disclosure']} but dates imply {calc}")
        exp = completeness(r)
        if exp is not None and r["completeness_score"].strip():
            if abs(float(r["completeness_score"]) - exp) > 0.011:
                problems.append(f"{rid}: completeness_score={r['completeness_score']} but fields imply {exp}")
        if not r["source_doc_ids"].strip():
            problems.append(f"{rid}: no source_doc_ids — every incident needs a public source")

    print(f"{len(rows)} incidents, {len(problems)} problems")
    for p in problems:
        print("  -", p)
    if not rows:
        return

    print("\nBy developer:")
    for k, v in sorted(Counter(r["developer"] for r in rows).items()):
        print(f"  {k}: {v}")
    print("\nBy category:")
    for k, v in sorted(Counter(r["category"] for r in rows).items()):
        print(f"  {k}: {v}")
    print("\nSurfaced by:")
    for k, v in sorted(Counter(r["surfaced_by"] for r in rows).items()):
        print(f"  {k}: {v}")

    lat = [int(r["days_to_disclosure"]) for r in rows if r["days_to_disclosure"].strip()]
    if lat:
        lat.sort()
        med = lat[len(lat) // 2]
        within72h = sum(1 for d in lat if d <= 3)
        print(f"\nDisclosure latency (n={len(lat)}): median {med} days; "
              f"{within72h} within 3 days; max {lat[-1]} days")

    print("\nField completeness (share 'present'):")
    for f in F_FIELDS:
        applicable = [r[f] for r in rows if r[f] != "n.a."]
        if applicable:
            share = sum(1 for v in applicable if v == "present") / len(applicable)
            print(f"  {f}: {share:.0%} of {len(applicable)}")


if __name__ == "__main__":
    main(sys.argv[1] if len(sys.argv) > 1 else DEFAULT)
